structs.MinimizerResult:
typedef struct
{
    __uint128_t minimizer_hash;
    size_t kmer_position;
    size_t smer_position;
} MinimizerResult;

functions.base_to_bits:
static inline uint8_t base_to_bits(char base)
{
    switch (base)
    {
    case 'A':
    case 'a':
        return 0;
    case 'C':
    case 'c':
        return 1;
    case 'G':
    case 'g':
        return 2;
    case 'T':
    case 't':
        return 3;
    default:
        return 0;
    }
}

functions.complement_base:
static inline uint8_t complement_base(uint8_t base)
{
    return 3 - base;
}

functions.add_minimizer:
static void add_minimizer(MinimizerResult *results, int *size, __uint128_t minimizer_hash, size_t kmer_position,
                          size_t smer_position)
{
    results[*size].minimizer_hash = minimizer_hash;
    results[*size].kmer_position = kmer_position;
    results[*size].smer_position = smer_position;
    (*size)++;
}

functions.compute_closed_syncmers:
void compute_closed_syncmers(const char *sequence_input, int len, int K, int S, MinimizerResult *results,
                             int *num_results)
{
    *num_results = 0;
    if (len < K)
    {
        fprintf(stderr, "Sequence length is less than K\n");
        return;
    }
    size_t num_s_mers = len - S + 1;
    __uint128_t *s_mer_hashes = (__uint128_t *)malloc(num_s_mers * sizeof(__uint128_t));
    __uint128_t mask = (((__uint128_t)1) << (2 * S)) - 1;
    __uint128_t hash_fwd = 0, hash_rev = 0;
    __uint128_t rc_shift = 2 * (S - 1);
    for (size_t i = 0; i < len; i++)
    {
        uint8_t base = base_to_bits(sequence_input[i]);
        hash_fwd = ((hash_fwd << 2) | base) & mask;
        uint8_t comp_base = complement_base(base);
        hash_rev = ((hash_rev >> 2) | ((__uint128_t)comp_base << rc_shift)) & mask;
        if (i >= S - 1)
        {
            size_t s_mer_pos = i - S + 1;
            __uint128_t canonical_hash = (hash_fwd < hash_rev) ? hash_fwd : hash_rev;
            s_mer_hashes[s_mer_pos] = canonical_hash;
        }
    }
    size_t window_size = K - S + 1;
    size_t *deque = (size_t *)malloc(num_s_mers * sizeof(size_t));
    size_t front = 0, back = 0;
    for (size_t i = 0; i < num_s_mers; i++)
    {
        while (back > front && s_mer_hashes[deque[back - 1]] > s_mer_hashes[i])
        {
            back--;
        }
        deque[back++] = i;
        if (i >= window_size && deque[front] <= i - window_size)
        {
            front++;
        }
        if (i >= window_size - 1)
        {
            size_t min_pos = deque[front];
            size_t kmer_pos = i - window_size + 1;
            if (min_pos == kmer_pos || min_pos == kmer_pos + K - S)
            {
                add_minimizer(results, num_results, s_mer_hashes[min_pos], kmer_pos, min_pos);
            }
        }
    }
    free(s_mer_hashes);
    free(deque);
}

functions.compute_closed_syncmers_naive:
void compute_closed_syncmers_naive(const char *sequence, size_t seq_len, int K, int S, MinimizerResult *results,
                                   int *num_results)
{
    *num_results = 0;
    __uint128_t mask = (((__uint128_t)1) << (2 * S)) - 1;
    for (size_t i = 0; i <= seq_len - K; i++)
    {
        __uint128_t min_hash = ~((__uint128_t)0);
        size_t min_pos_in_kmer = 0;
        for (size_t j = 0; j <= K - S; j++)
        {
            size_t s_mer_pos = i + j;
            __uint128_t hash_fwd = 0;
            __uint128_t hash_rev = 0;
            for (size_t k = 0; k < S; k++)
            {
                uint8_t base = base_to_bits(sequence[s_mer_pos + k]);
                hash_fwd = (hash_fwd << 2) | base;
            }
            hash_fwd &= mask;
            for (size_t k = 0; k < S; k++)
            {
                size_t pos = s_mer_pos + S - 1 - k;
                uint8_t base = base_to_bits(sequence[pos]);
                uint8_t comp_base = complement_base(base);
                hash_rev = (hash_rev << 2) | comp_base;
            }
            hash_rev &= mask;
            __uint128_t canonical_hash = (hash_fwd < hash_rev) ? hash_fwd : hash_rev;
            if (canonical_hash < min_hash)
            {
                min_hash = canonical_hash;
                min_pos_in_kmer = j;
            }
        }
        if (min_pos_in_kmer == 0 || min_pos_in_kmer == K - S)
        {
            results[*num_results].kmer_position = i;
            results[*num_results].smer_position = i + min_pos_in_kmer;
            results[*num_results].minimizer_hash = min_hash;
            (*num_results)++;
        }
    }
}

